import std.collection.*

func resolveItem(q: ArrayDeque<Int64>, t: Int64): Int64 {
var n:Int64=0
while (!q.isEmpty()) { if ((q.last ?? 0) > t) {break}; q.removeLast(); n+=1 }
n
}

main() {
let item0 = ArrayDeque<Int64>()
item0.addLast(2)
item0.addLast(5)
item0.addLast(1)
let actual0 = resolveItem(item0, 2)
println(actual0 == 1 && item0.toArray() == [5, 1])
let item1 = ArrayDeque<Int64>()
item1.addLast(-3)
item1.addLast(4)
let actual1 = resolveItem(item1, 3)
println(actual1 == 1 && item1.toArray() == [4])
}

