func resolveItem(q: TreeMap<Int64,Int64>, t: Int64): Int64 {
for ((k,v) in q.forward(t)) {return v}
-99
}

main() {
let item0 = TreeMap<Int64,Int64>()
item0.add(2, -2)
item0.add(5, 6)
item0.add(1, 21)
let actual0 = resolveItem(item0, 2)
let witness0 = ArrayList<Int64>()
for ((k,v) in item0) { witness0.add(k); witness0.add(v) }
println(actual0 == 6 && witness0.toArray() == [1, 21, 2, -2, 5, 6])
let item1 = TreeMap<Int64,Int64>()
item1.add(-3, 3)
item1.add(4, 7)
let actual1 = resolveItem(item1, 3)
let witness1 = ArrayList<Int64>()
for ((k,v) in item1) { witness1.add(k); witness1.add(v) }
println(actual1 == 7 && witness1.toArray() == [-3, 3, 4, 7])
}

